export async function runDatabaseRestore(opts: RunDatabaseRestoreOptions): Promise<void> {
  // Validate the entire compressed stream before any database mutation. A private
  // on-disk snapshot bounds memory and prevents re-reading a changed archive.
  // 发行层 1.1.6：私有临时目录优先建在备份文件同目录（与外接盘部署一致，不占内置盘 tmp）；
  // 该目录不可写（只读卷/权限）时才退回系统临时目录。mkdtemp 创建的目录权限为 0700。
  const directory = await mkdtemp(join(dirname(opts.backupFile), ".paperclip-restore-"))
    .catch(error => {
      if (["EACCES", "EPERM", "EROFS"].includes((error as NodeJS.ErrnoException).code ?? "")) return mkdtemp(join(tmpdir(), "paperclip-restore-"));
      throw error;
    });
  const backupFile = join(directory, "validated.sql");
  try {
    const output = createWriteStream(backupFile, { flags: "wx", mode: 0o600 });
    if (opts.backupFile.endsWith(".gz")) {
      // 发行层 1.1.6：解压字节上限，防止压缩炸弹写满外接盘。gzip 理论最大压缩比约 1032:1；
      // pg_dump 纯文本实际一般 5–20 倍，取 200 倍留足余量，并以 8 GiB 为下限覆盖小归档；可显式配置。
      const compressedBytes = (await statFile(opts.backupFile)).size;
      const limit = opts.maxDecompressedBytes ?? Math.max(compressedBytes * 200, 8 * 1024 ** 3);
      let written = 0;
      const guard = new Transform({
        transform(chunk: Buffer, _encoding, callback) {
          written += chunk.length;
          if (written > limit) {
            const error = Object.assign(new Error(`Decompressed backup exceeds the ${limit}-byte restore limit`), { code: "PAPERCLIP_RESTORE_TOO_LARGE" });
            callback(error);
            return;
          }
          callback(null, chunk);
        },
      });
      await pipeline(createReadStream(opts.backupFile), createGunzip(), guard, output);
    } else {
      await pipeline(createReadStream(opts.backupFile), output);
    }
    await restoreValidatedDatabase({ ...opts, backupFile }, basename(opts.backupFile));
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

